// CauldronTile.cpp
void CauldronTile::handleRain(Level *level, int x, int y, int z)
{
	if (level->random->nextInt(20) != 1) return;

	int data = level->getData(x, y, z);

	if (data < 3)
	{
		level->setData(x, y, z, data + 1);
	}
}

